  scrollend = scrollListener.promiseScrollingStopped();
  scrollListener.setScrollExpectation(-1);

  // Page up a few times then delete some messages.
  await delayThenPressAndWaitForSelect(0, "KEY_PageUp");
  await delayThenPressAndWaitForSelect(60, "KEY_PageUp");
  await delayThenPressAndWaitForSelect(60, "KEY_PageUp");
  await delayThenPressAndWaitForSelect(400, "KEY_Delete");
  await delayThenPressAndWaitForSelect(80, "KEY_Delete");

  await scrollend;

  Assert.equal(
    threadTree.getFirstVisibleIndex(),
    threadTree.selectedIndex,
    "selected row should be the first visible row"
  );

  // Page down a few times then delete some messages.

  scrollend = scrollListener.promiseScrollingStopped();
  scrollListener.setScrollExpectation(1);

  await delayThenPressAndWaitForSelect(60, "KEY_PageDown");
  await delayThenPressAndWaitForSelect(60, "KEY_PageDown");
  await delayThenPressAndWaitForSelect(60, "KEY_PageDown");
  await delayThenPressAndWaitForSelect(300, "KEY_Delete");
  await delayThenPressAndWaitForSelect(80, "KEY_Delete");
  await delayThenPressAndWaitForSelect(80, "KEY_Delete");
  await delayThenPressAndWaitForSelect(80, "KEY_Delete");
  await delayThenPressAndWaitForSelect(80, "KEY_Delete");

  await scrollend;

  Assert.equal(
    threadTree.getLastVisibleIndex(),
    threadTree.selectedIndex,
    "selected row should be the last visible row"
  );
  // Select a message somewhere in the middle then delete it.
  // Shouldn't scroll.
  scrollListener.setNoScrollExpectation();
  const targetIndex = threadTree.selectedIndex - 10;
  const selectEvent = BrowserTestUtils.waitForEvent(
    threadTree,
    "select",
    false,
    () => threadTree.selectedIndex == targetIndex
  );
  threadTree.selectedIndex = targetIndex;
  await selectEvent;
  await delayThenPressAndWaitForSelect(80, "KEY_Delete");
  await delayThenPressAndWaitForSelect(80, "KEY_Delete");
  await delayThenPressAndWaitForSelect(80, "KEY_Delete");

  Assert.less(
    threadTree.getFirstVisibleIndex(),
    threadTree.selectedIndex,
    "selected row should be below the first visible row"
  );
  Assert.greater(
    threadTree.getLastVisibleIndex(),
    threadTree.selectedIndex,
    "selected row should be above the last visible row"
  );

  threadTree.removeEventListener("scrollend", scrollListener);
});
